mapper.select:
select user_id, email, password, user_name, phone_number, user_type, created_at, updated_at
from Users
where email = #{email}

select user_id, email, user_name, phone_number, user_type, created_at, updated_at, deleted_at
from Users
where user_id = #{userId}

mapper.update:
update Users
set password = #{password},
    user_name = #{userName},
    phone_number = #{phoneNumber}
where email = #{email}

mapper.select:
SELECT u.user_id, u.email, u.user_name, u.phone_number, u.user_type, u.created_at, u.updated_at, u.deleted_at, r.request_id AS pending_request_id, r.salon_name AS pending_salon_name FROM Users u LEFT JOIN OwnerRequests r ON r.user_id = u.user_id AND r.status = 'pending' WHERE 1=1
and deleted_at is not null
and deleted_at is null
and (user_name like concat('%', #{keyword}, '%') or email like concat('%', #{keyword}, '%'))
and user_type = #{userType}
order by user_id desc limit #{offset}, #{size}

mapper.update:
update Users
set user_type = 'customer'
where user_id = #{userId}

update Users
set user_type = 'owner'
where user_id = #{userId}
